# 3.6 — "dòng thời gian crash" kiểu Reliability Monitor dựng lại từ Application log: 1000 Application Error, 1001 Windows Error Reporting, 1002 Application Hang.
@ps evtx-rec mau/Application.evtx mau/dbc-many-events-application.evtx | ConvertFrom-Json | Where-Object { ($_.id -eq 1000 -and $_.nguon -eq 'Application Error') -or ($_.id -eq 1002 -and $_.nguon -eq 'Application Hang') } | Group-Object nguon,{ $_.data.'#text'[0] } | Sort-Object Count -Descending | Select-Object -First 10 Count,Name | Format-Table -AutoSize
@ps evtx-rec mau/Application.evtx | ConvertFrom-Json | Where-Object { $_.id -eq 1000 -and $_.nguon -eq 'Application Error' } | Select-Object -First 1 | ForEach-Object { $d = $_.data.'#text'; "Luc: $($_.t.ToString('s'))Z  may: $($_.may)"; $ten = 'Ung dung','Phien ban','Dau thoi gian','Module loi','Phien ban module','Dau thoi gian module','Ma ngoai le','Offset','PID (hex)','Gio bat dau','Duong dan','Duong dan module','Report Id'; for ($i = 0; $i -lt [math]::Min($d.Count,$ten.Count); $i++) { "{0,-22} = {1}" -f $ten[$i], $d[$i] } }
@ps evtx-rec mau/Application.evtx | ConvertFrom-Json | Where-Object { $_.id -eq 1001 -and $_.nguon -eq 'Windows Error Reporting' } | Group-Object { $_.data.'#text'[2] } | Sort-Object Count -Descending | Select-Object -First 6 Count,@{n='Loai su kien WER';e={$_.Name}} | Format-Table -AutoSize
@ps evtx-rec mau/Application.evtx | ConvertFrom-Json | Where-Object { $_.id -eq 1001 -and $_.nguon -eq 'Windows Error Reporting' -and $_.data.'#text'[2] -eq 'APPCRASH' } | Select-Object -First 1 | ForEach-Object { "Luc: $($_.t.ToString('s'))Z"; $_.data.'#text' | ForEach-Object -Begin { $i = 0 } -Process { if ($_ -ne '') { "  [{0,2}] {1}" -f $i, $_ }; $i++ } }
@ps evtx-rec mau/Application.evtx mau/dbc-many-events-application.evtx | ConvertFrom-Json | Where-Object { $_.muc -in 'Critical','Error' -or ($_.id -eq 1000 -and $_.nguon -eq 'Application Error') } | Group-Object { $_.may }, { $_.t.ToString('yyyy-MM') } | Sort-Object Count -Descending | Select-Object -First 8 Count,Name | Format-Table -AutoSize
